"t": "s",
"h": "Learning Theory",
"g": "Behaviorism and cognitive theory combine to explain how people learn.",
"obj": "Explain the two major learning theories and how instructors combine them.",
"pts": [
"**Learning theory**: principles explaining how people acquire skills, knowledge, and attitudes; 2 major concepts: Behaviorism and Cognitive Theory.",
"**Behaviorism**: encourage progress with rewards (positive reinforcement rather than none or punishment); popularity has waned.",
"**Cognitive theory**: learning changes how a learner thinks, understands, feels. Branches: Information Processing Theory and Constructivism.",
"**Information processing**: brain selects, processes, stores, retrieves info and uses feedback. **Constructivism**: match new info to existing info, build connections.",
"Behavioral + Cognitive: use the best of each; measure behavioral outcomes while promoting cognitive learning."
],
"ref": "AIH Ch 3",
"l2": [
"2 major concepts: **Behaviorism** (rewards) and **Cognitive theory** (changes how learners think).",
"Combine both: measure behavioral outcomes while promoting cognitive learning."
],
