"t": "s",
"h": "Principles of Learning (REEPIR)",
"g": "Six principles (REEPIR) shape how instruction should be delivered.",
"obj": "Explain each principle and how it shapes instruction.",
"pts": [
"**Readiness**: basic needs met; clear reason to learn. Communicate clear objectives; introduce topics in logical order.",
"**Exercise**: connections strengthen with practice, weaken without; best in real-world context.",
"**Effect**: satisfying outcomes are repeated; include elements that make the learner feel satisfaction.",
"**Primacy**: what is learned first creates a strong, almost unshakable impression.",
"**Intensity**: vivid, dramatic, exciting experiences teach more than routine ones.",
"**Recency**: things most recently learned are best remembered."
],
