"h": "Memory",
"g": "Memory moves from sensory to short-term to long-term storage.",
"obj": "Describe sensory, short-term, and long-term memory.",
"pts": [
"**Sensory**: scans stimuli by personal importance; dramatic or multi-sense input more likely to register; passed on within seconds.",
"**Short-term**: like a control tower; holds info about 30 seconds; repetition and chunking help.",
"**Recoding** (relating new info to existing knowledge) is when actual learning begins.",
"Short-term operations: **iconic** (visual), **acoustic** (sound), **working** memory.",
"**Long-term**: relatively permanent, unlimited; the more effective the coding, the easier the recall."
],
