"h": "Defense Mechanisms",
"g": "Defense mechanisms are subconscious reactions that protect the ego.",
"obj": "Recognize subconscious ego-protecting reactions in learners.",
"pts": [
"Subconscious, almost automatic reactions that soften failure, relieve guilt, protect personal worth.",
"**Repression** (thoughts pushed to the unconscious), **Denial** (refuse threatening reality), **Compensation** (emphasize a stronger quality).",
"**Projection** (blame others), **Rationalization** (sincerely believed excuses for unacceptable actions).",
"**Reaction formation** (develop opposite attitudes), **Fantasy** (daydream instead of act), **Displacement** (shift emotion to a less threatening substitute)."
],
