"h": "Weather detection",
"g": "Onboard weather tools have limits; datalink is for strategic avoidance.",
"obj": "Explain onboard radar, lightning detection and datalink limits.",
"pts": [
"Radar: reflects off precipitation; green light, yellow moderate, red severe. **Attenuation**: heavy rain hides weather behind it.",
"Lightning detection: 360 deg view; **radial spread** (strong strikes look closer) and **ionospheric skip** (false strikes from storms up to 1,000 NM).",
"**FIS-B** over ADS-B UAT: NEXRAD, METAR/TAF, PIREPs, AIRMET/SIGMET, NOTAMs; can be **15-20 min old**, needs line of sight to a ground station.",
"AC 00-63: datalink is for **strategic** avoidance only, not close-in maneuvering; augment, don't replace, briefings."
],
