"h": "Atmospheric composition & layers",
"g": "The atmosphere is mostly four gases arranged in five layers.",
"obj": "Describe what the atmosphere is made of and its five layers.",
"pts": [
"4 gases make up 99.998%: **nitrogen, oxygen, argon, carbon dioxide**.",
"**Troposphere**: surface to about 36,000 ft (varies with temperature); temp decreases with height; almost all weather. Top = **tropopause**.",
"**Stratosphere**: to 31 miles; temp increases with height (UV absorption); airliners cruise low in it to avoid turbulence/convection.",
"**Mesosphere** (to ~53 mi, cooling), **thermosphere** (to 430 mi, up to 2,000 C), **exosphere** (to 6,200 mi, satellites).",
"**Standard atmosphere**: 15 C / 59 F and 29.92 in Hg - an average for all latitudes, seasons, altitudes."
],
"ref": "Aviation Weather Handbook",
