"t": "s",
"h": "Airframe icing",
"g": "Icing cuts lift and thrust; exit the precipitation or freezing level.",
"obj": "Recognize icing and respond.",
"pts": [
"Be alert in visible moisture and temps near freezing (-10 to +2 C); watch the windscreen and wings (flashlight at night).",
"Effects cumulative: less thrust and lift, more drag and weight, higher stall speed.",
"**1/2 inch** of ice can cut lift by 50% and increase frictional drag by 50%.",
"Use deice/anti-ice per manufacturer; leave the precipitation or go to above-freezing altitude (not necessarily lower); else land at nearest suitable airport."
],
"l2": [
"Be alert in visible moisture, -10 to +2 C.",
"1/2 inch of ice can cut lift by 50%.",
"Leave precipitation, go above freezing, or land at nearest suitable airport."
],
