"h": "Primary & Supporting Method",
"g": "Primary instruments give direct information; supporting ones show trends.",
"obj": "Explain how primary and supporting instruments are assigned for each maneuver.",
"pts": [
"Direct extension of **Control & Performance**: Establish, Trim, Crosscheck, Adjust.",
"Attitude is set with the attitude indicator and power instruments, but each maneuver has specific primary and supporting instruments.",
"**Primary**: gives the most pertinent information for a specific parameter.",
"**Supporting**: shows a trend away from the desired parameter (no direct indication); forewarns of an impending deviation.",
"An efficient crosscheck catches and corrects these deviations early."
],
"ref": "Instrument Flying Handbook",
