"Center the CDI with TO; turn to that heading. Centered with TO, the needle tail shows the radial you're on.",
"Crosswind from the right: drift left, CDI moves right; correct right, then crab into the wind. Don't home.",
"Station passage: TO flips to FROM. **Reverse sensing**: flying TO with a FROM indication (or vice versa) the CDI reads opposite."
